(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const seasons=['Spring','Summer','Autumn','Winter'];
const names=['Mira Venn','Tomas Reed','Anya Sol','Elias Marlow','Neri Vale','Oren Pike','Sela Thorn','Ivo Sen','Lina Crow','Pavel Rook','Yara Moss','Kellan Ward','Nadia Elm','Bram Ash','Talia Fen','Rafi Calder','Juno Bell','Marek Hale','Asha Wyn','Cora Dain'];
const jobs=['Field hand','Weaver','Carpenter','Herbalist','Teacher','Miller','Trader','Fisher','Builder','Healer','Courier','Guard'];
const traits=['Patient','Curious','Steadfast','Warm-hearted','Ambitious','Cautious','Inventive','Generous','Restless','Principled','Witty','Observant'];
const orgKinds=['Cooperative','Guild','School','Garden circle','Council','Workshop'];
const hash=s=>{let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return h>>>0};
function rng(seed){let x=seed>>>0;return()=>{x+=0x6D2B79F5;let t=x;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function person(i,r,parents=[]){const first=names[i%names.length].split(' ')[0],surname=names[i%names.length].split(' ')[1];return{id:'p'+String(i+1).padStart(3,'0'),name:i<names.length?names[i]:`${first} ${surname}`,age:18+Math.floor(r()*55),job:jobs[Math.floor(r()*jobs.length)],traits:[traits[Math.floor(r()*traits.length)],traits[Math.floor(r()*traits.length)]],wealth:15+Math.floor(r()*90),health:68+Math.floor(r()*31),mood:48+Math.floor(r()*46),belief:['Commons','Stewardship','Tradition'][Math.floor(r()*3)],home:'Aster Hollow',parents,children:[],friends:[],memory:['A childhood spent beneath the old willows.'],history:[],born:1+Math.floor(r()*35),reputation:Math.floor(r()*40),skills:{craft:Math.floor(r()*5),care:Math.floor(r()*5),trade:Math.floor(r()*5)},alive:true,watched:false}}
function seedWorld(){const r=rng(784323);const people=names.map((_,i)=>person(i,r));const links=[['p001','p002','Friendship'],['p001','p004','Family'],['p003','p007','Romance'],['p005','p009','Mentorship'],['p002','p006','Rivalry'],['p010','p011','Family'],['p008','p012','Friendship'],['p013','p014','Marriage'],['p015','p016','Professional'],['p017','p018','Friendship'],['p019','p020','Family']];for(const [a,b,type]of links){let x=people.find(p=>p.id===a),y=people.find(p=>p.id===b);if(x&&y){x.friends.push({id:b,type,trust:55+Math.floor(r()*40),affection:40+Math.floor(r()*50)});y.friends.push({id:a,type,trust:45+Math.floor(r()*45),affection:35+Math.floor(r()*55)})}}
const rel=(id,name,kind,members,objective)=>({id,name,kind,founder:members[0],members,leader:members[0],objective,resources:35+Math.floor(r()*60),influence:12+Math.floor(r()*30),stability:72+Math.floor(r()*25),age:1+Math.floor(r()*20)});
return{seed:784323,day:1,year:1,season:0,paused:false,speed:1,view:'world',subview:'all',role:'Observer',focus:'p001',people,relationships:links.map(x=>({a:x[0],b:x[1],type:x[2],trust:50+Math.floor(r()*50),affection:30+Math.floor(r()*70),loyalty:35+Math.floor(r()*60),influence:15+Math.floor(r()*70)})),organizations:[rel('o1','Aster Field Cooperative','Cooperative',['p001','p002','p006','p014'],'Keep grain affordable and share seed.'),rel('o2','Lantern & Loom Guild','Guild',['p004','p009','p013'],'Protect the work and craft of makers.'),rel('o3','Willowbank School','School',['p005','p012','p018'],'Pass practical knowledge to the next generation.')],events:[{day:1,year:1,icon:'✦',title:'A new chapter begins',text:'Twenty neighbors make their home in Aster Hollow, beside the bend in the river.',type:'history'}],food:76,water:84,wellbeing:71,approval:64,price:22,unemployment:8,wealth:59,production:68,innovation:12,tax:8,weather:'Mild rains',tension:18,yearValues:[60,64,61,66,68,67,71,68],savedAt:Date.now(),settlement:{name:'Aster Hollow',population:20,houses:13,fields:8,workshops:3,roads:5,waterworks:2,commons:3,growth:1},policies:{tax:8,relief:false},lastEventDay:1};}
let state;try{state=JSON.parse(localStorage.getItem('livingWorldSave'))||seedWorld()}catch{state=seedWorld()}
let toastTimer;
function save(){state.savedAt=Date.now();localStorage.setItem('livingWorldSave',JSON.stringify(state));$('#saveStatus').textContent='WORLD SAVED';}
function showToast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
function currentDate(){return`Day ${String(((state.day-1)%90)+1).padStart(2,'0')} · ${seasons[Math.floor(((state.day-1)%360)/90)]}, Year ${state.year}`}
function activePeople(){return state.people.filter(p=>p.alive)}
function focusPerson(){return state.people.find(p=>p.id===state.focus)||state.people[0]}
function metricLabel(v){return v>75?'Thriving':v>55?'Steady':v>35?'Strained':'Critical'}
function pushEvent(title,text,icon='•',type='social'){state.events.unshift({day:state.day,year:state.year,title,text,icon,type});state.events=state.events.slice(0,100);state.lastEventDay=state.day}
function newRelationship(a,b,type){if(a===b||state.relationships.some(x=>x.a===a&&x.b===b||x.a===b&&x.b===a))return;let trust=45+Math.floor(Math.random()*35);state.relationships.push({a,b,type,trust,affection:35+Math.floor(Math.random()*55),loyalty:30+Math.floor(Math.random()*55),influence:20+Math.floor(Math.random()*55)});let pa=state.people.find(p=>p.id===a),pb=state.people.find(p=>p.id===b);if(pa&&!pa.friends.some(x=>x.id===b))pa.friends.push({id:b,type,trust,affection:50});if(pb&&!pb.friends.some(x=>x.id===a))pb.friends.push({id:a,type,trust,affection:50})}

