function activePeople(){return state.people.filter(p=>p.alive)}
function focusPerson(){return state.people.find(p=>p.id===state.focus)||state.people[0]}
function metricLabel(v){return v>75?'Thriving':v>55?'Steady':v>35?'Strained':'Critical'}
function pushEvent(title,text,icon='•',type='social'){state.events.unshift({day:state.day,year:state.year,title,text,icon,type});state.events=state.events.slice(0,100);state.lastEventDay=state.day}
function random(){state.seed=(Math.imul(state.seed,1664525)+1013904223)>>>0;return state.seed/4294967296}
function newRelationship(a,b,type){if(a===b||state.relationships.some(x=>x.a===a&&x.b===b||x.a===b&&x.b===a))return;let trust=45+Math.floor(random()*35);state.relationships.push({a,b,type,trust,affection:35+Math.floor(random()*55),loyalty:30+Math.floor(random()*55),influence:20+Math.floor(random()*55)});let pa=state.people.find(p=>p.id===a),pb=state.people.find(p=>p.id===b);if(pa&&!pa.friends.some(x=>x.id===b))pa.friends.push({id:b,type,trust,affection:50});if(pb&&!pb.friends.some(x=>x.id===a))pb.friends.push({id:a,type,trust,affection:50})}
function lifeEvent(p,title,description,icon='✦'){p.memory.unshift(description);p.memory=p.memory.slice(0,8);p.history.unshift({title,day:state.day,year:state.year});p.mood=Math.min(100,Math.max(10,p.mood+(title.includes('loss')?-10:5)));pushEvent(title,description,icon,'life')}
function tick(){state.day++;let season=Math.floor(((state.day-1)%360)/90);let weatherRoll=random();if(weatherRoll<.035)state.weather=['A dry spell','Heavy rain','Clear skies','Cold snap'][Math.floor(random()*4)];else if(weatherRoll>.94)state.weather='Mild rains';
let harvest=(season===2?10:season===1?6:season===0?2:-2)+(state.weather==='A dry spell'?-13:state.weather==='Heavy rain'?-5:state.weather==='Mild rains'?3:0)+(state.settlement.fields-8)*.6;state.food=Math.max(0,Math.min(100,state.food+harvest-(state.settlement.population/20)*2.1));state.water=Math.max(0,Math.min(100,state.water+(state.weather==='Heavy rain'?8:state.weather==='A dry spell'?-7:1)-state.settlement.population*.08));
state.price=Math.max(8,Math.min(85,Math.round(state.price+(55-state.food)*.035+(state.wealth-50)*-.012+(state.policies.relief?-1:0))));state.production=Math.max(10,Math.min(100,state.production+(state.innovation*.006)+(state.unemployment>20?-1.5:.25)+(state.food<20?-2:0)));state.wellbeing=Math.max(10,Math.min(100,Math.round((state.food*.35+state.water*.2+state.wealth*.18+state.approval*.15+(100-state.tension)*.12))));
let folks=activePeople();for(const p of folks){p.age+=1/360;p.mood=Math.max(5,Math.min(100,p.mood+(state.food<25?-2:state.wellbeing>65?.25:-.3)+(p.traits.includes('Warm-hearted')?.2:0)));p.wealth=Math.max(0,Math.min(999,p.wealth+(p.job==='Trader'?1.1:p.job==='Field hand'?.45:.65)-state.price*.012-(state.policies.tax*.025)));if(p.health<30&&random()<.018){p.alive=false;lifeEvent(p.name+' is lost','Aster Hollow mourns '+p.name+'. Their stories are carried by those who knew them.','†');for(const c of state.people.filter(c=>c.parents.includes(p.id))){c.wealth+=Math.floor(p.wealth/Math.max(1,p.children.length));c.memory.unshift('Inherited a keepsake and a little security from '+p.name+'.')}}else if(p.health<100&&random()<.01)p.health=Math.min(100,p.health+2);
}
state.settlement.population=Math.max(1,folks.filter(p=>p.alive).length);state.unemployment=Math.max(2,Math.min(45,Math.round(9+(state.price-22)*.35+(state.production-65)*-.17+(state.food<20?8:0))));state.wealth=Math.max(12,Math.min(95,Math.round(state.wealth+(state.production-60)*.035-(state.price-22)*.04-(state.unemployment-8)*.04)));state.tension=Math.max(3,Math.min(95,Math.round(state.tension+(state.wellbeing<40?1.8:state.wellbeing>70?-.7:.12)+(state.approval<40?1:.0))));state.approval=Math.max(10,Math.min(95,Math.round(70-(state.price-22)*.28-(state.tension-18)*.14+(state.policies.relief?5:0)-(state.policies.tax-8)*.4)));
for(const o of state.organizations){o.age++;o.resources=Math.max(0,Math.min(100,o.resources+(state.food>45?1:-1)));o.influence=Math.max(5,Math.min(95,o.influence+(o.members.length>3?.3:-.1)+(state.tension>40&&o.kind==='Council'?.7:0)));if(random()<.014&&activePeople().length>o.members.length){let candidates=activePeople().filter(p=>!o.members.includes(p.id));if(candidates.length){let recruit=candidates[Math.floor(random()*candidates.length)];o.members.push(recruit.id);lifeEvent(recruit.name+' joined '+o.name,'Through a trusted friend, '+recruit.name+' joined '+o.name+'.','◇')}}}
if(state.day%90===0){state.season=(state.season+1)%4;pushEvent(seasons[state.season]+' arrives','The turning season reshapes work, food, and the rhythm of life in '+state.settlement.name+'.','◷','history')}
if(state.day%360===0){state.year++;state.yearValues.push(state.wellbeing);state.yearValues=state.yearValues.slice(-12);for(const p of activePeople())p.age+=1;let r=random();if(state.food<20){let loss=3+Math.floor(random()*5);state.settlement.population=Math.max(1,state.settlement.population-loss);state.people.slice(-loss).forEach(p=>p.alive=false);pushEvent('The lean season','Harvests failed. Food prices climbed, several families left for the coast, and trust in the council weakened.','!','crisis');state.tension+=12}else if(r<.25){const parent=activePeople().filter(p=>p.age>22&&p.age<38)[Math.floor(random()*Math.max(1,activePeople().filter(p=>p.age>22&&p.age<38).length))];if(parent){let baby=person(state.people.length,()=>random(),[parent.id]);baby.name=['Elowen','Soren','Pia','Niko','Iris','Tarin'][Math.floor(random()*6)]+' '+parent.name.split(' ').pop();baby.age=0;baby.home=parent.home;baby.wealth=Math.floor(parent.wealth*.2);baby.traits=parent.traits.slice();baby.memory=['Born in '+seasons[season]+' of Year '+state.year+'.'];state.people.push(baby);parent.children.push(baby.id);state.settlement.population++;lifeEvent(baby.name+' was born','A new generation begins: '+baby.name+' inherits '+parent.name+'’s family name, stories, and a place in the community.','✿')}}else if(r<.45){let p=activePeople()[Math.floor(random()*activePeople().length)];if(p){p.skills.craft++;state.innovation+=2;lifeEvent('A new technique takes root',p.name+' found a more efficient way to work the river clay. The potters’ guild is already sharing it.','✧');state.production+=4}}
if(state.tension>68&&state.approval<35){pushEvent('A call for change','Growing hardship and shared grievances bring neighbors into the square. The council agrees to hear a reform petition.','⚑','politics');state.tension-=15;state.approval+=9}else if(state.price>48){pushEvent('Market unease','Scarcity has lifted prices; the cooperative opens its reserve stores, easing pressure on household budgets.','⌁','economy');state.food=Math.min(100,state.food+8);state.price-=6}else if(r<.22){let p=activePeople()[Math.floor(random()*activePeople().length)];if(p){p.reputation+=10;state.organizations[0].influence+=3;lifeEvent(p.name+' became a local voice',p.name+'’s patient organizing around fair grain prices earned the trust of neighbors.','⚑');newRelationship(p.id,activePeople()[Math.floor(random()*activePeople().length)].id,'Political alliance')}}
if(state.settlement.population>state.settlement.houses*2){state.settlement.houses++;pushEvent('A new home is raised','The settlement has outgrown its old boundary. Neighbors build another row of homes beside the north road.','⌂','settlement')}if(state.settlement.population>24&&random()<.4){state.settlement.fields++;state.settlement.workshops+=random()<.35?1:0;state.settlement.growth++;pushEvent('The village expands','A community meeting sets aside land for another shared field and a new workshop.','⌂','settlement')}
}
if(random()<.04){let rel=state.relationships[Math.floor(random()*state.relationships.length)];if(rel){rel.trust=Math.max(10,Math.min(99,rel.trust+(random()>.25?2:-6)));if(rel.trust<25&&random()<.3){pushEvent('A friendship cools','An unresolved disagreement has widened the distance between two neighbors.','↔');rel.trust+=4}}}
state.settlement.growth=Math.max(-20,Math.min(50,state.settlement.growth+(state.wellbeing>65?.1:-.2)));save();render();}

