width="19" height="19" rx="2"/><rect class="map-building" x="341" y="174" width="24" height="21" rx="2"/><path class="map-landmark" d="M338 175l15-13 15 13z"/></g>${dots}<text class="map-label" x="280" y="220">ASTER HOLLOW</text><text class="map-label" x="64" y="165">NORTH FIELDS</text><text class="map-label" x="452" y="149">WILLOWBANK</text><text class="map-label" x="494" y="282">THE RIVER ROAD</text><circle cx="278" cy="128" r="3" fill="#b9955d"/><circle cx="372" cy="161" r="3" fill="#b9955d"/></svg>`}
function eventRows(events,count=3){return events.slice(0,count).map(e=>`<div class="event-row"><span class="event-marker">${e.icon||'•'}</span><div class="event-copy"><strong>${e.title}</strong><p>${e.text}</p></div><span class="event-time">Y${e.year} · D${String(e.day%360||360).padStart(2,'0')}</span></div>`).join('')||'<div class="empty-state">History is still being written.</div>'}
function worldView(){let p=focusPerson();let recent=state.events.slice(0,3);return`<div class="section-heading"><div><div class="section-kicker">A LIVING SIMULATION · ${state.role.toUpperCase()}</div><h1>Good morning, ${p.name.split(' ')[0]}.</h1><p>Life continues in Aster Hollow, whether you’re watching or not.</p></div><span class="legend"><i></i> People in the village</span></div><div class="overview-grid"><div class="map-card"><div class="map-head"><strong>${state.settlement.name}</strong><span>RIVER VALLEY · ${state.weather.toUpperCase()}</span></div><div class="map-key"><span><i></i> Residents</span><span>◆ Shared land</span></div>${mapSvg()}<div class="map-actions"><button class="small-action" data-action="build">＋ Build together</button><button class="small-action" data-view="people">♙ Meet a neighbor</button></div></div><div class="overview-side"><div class="panel-card population-card"><div class="card-title-row"><span class="card-title">COMMUNITY</span><span class="trend-pill">${state.settlement.growth>=0?'↗':'↘'} ${(Math.abs(state.settlement.growth)/10).toFixed(1)}%</span></div><div class="big-number">${state.settlement.population}<span style="font:400 12px 'DM Sans';letter-spacing:0;color:#7e887f"> neighbors</span></div><svg class="sparkline" viewBox="0 0 240 30" preserveAspectRatio="none"><path d="M0 24 C25 25 36 13 56 18 S84 22 107 12 141 21 161 10 188 13 207 6 227 9 240 3" fill="none" stroke="#81a075" stroke-width="2"/><path d="M0 24 C25 25 36 13 56 18 S84 22 107 12 141 21 161 10 188 13 207 6 227 9 240 3V30H0Z" fill="#dfe9d8" opacity=".55"/></svg></div><div class="panel-card vital-list"><div class="card-title-row"><span class="card-title">THE VILLAGE PULSE</span><span class="tiny-label">TODAY</span></div>${[['Food stores',state.food,'◍'],['Wellbeing',state.wellbeing,'♡'],['Public trust',state.approval,'⚑']].map(([n,v,icon])=>`<div class="vital"><span class="vital-icon">${icon}</span><div class="vital-text"><span>${n}</span><div class="meter"><i style="width:${v}%"></i></div></div><span class="vital-value">${Math.round(v)}%</span></div>`).join('')}</div></div></div><div class="below-grid"><div class="panel-card"><div class="panel-head"><h2>Threads of today</h2><button class="text-link" data-view="history">Open chronicle →</button></div>${eventRows(recent,3)}</div><div class="panel-card"><div class="panel-head"><h2>A life in focus</h2><button class="text-link" data-view="people">All people →</button></div><div class="person-feature" data-person="${p.id}"><div class="portrait">${initials(p.name)}</div><div><strong>${p.name}</strong><small>${p.age.toFixed(0)} years · ${p.job} · ${p.home}</small></div><span class="arrow">↗</span></div><p class="inspector-p" style="margin:10px 0 0">“${p.memory[0]}”</p></div></div>`}
function initials(name){return name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}

