function initials(name){return name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function tabs(items,active){return`<div class="view-tabs">${items.map(([id,label])=>`<button class="${active===id?'active':''}" data-subview="${id}">${label}</button>`).join('')}</div>`}
function peopleView(){let people=activePeople().filter(p=>state.subview==='all'||state.subview==='watched'&&p.watched||state.subview==='families'&&p.parents.length||state.subview==='influential'&&p.reputation>35);let q=(state.peopleQuery||'').toLowerCase();people=people.filter(p=>p.name.toLowerCase().includes(q)||p.job.toLowerCase().includes(q));return`<div class="section-heading"><div><div class="section-kicker">PERSISTENT IDENTITIES · ${state.people.length} RECORDS</div><h1>People & their stories</h1><p>Each person keeps a name, a history, and a place in the world.</p></div><button class="primary-btn" data-action="role">Choose a life ↗</button></div>${tabs([['all','Everyone'],['watched','Following'],['families','Families'],['influential','Influential']],state.subview)}<div class="list-toolbar"><input id="peopleSearch" class="search-input" placeholder="Search people, work, or place…" value="${state.peopleQuery||''}"><select class="filter-select" id="peopleSort"><option value="name">Sort: Name</option><option value="age">Sort: Age</option><option value="reputation">Sort: Influence</option></select><span class="tiny-label">${people.length} PEOPLE</span></div><div class="table-card">${[...people].sort((a,b)=>state.sortBy==='age'?b.age-a.age:state.sortBy==='reputation'?b.reputation-a.reputation:a.name.localeCompare(b.name)).slice(0,30).map(p=>`<div class="person-row" data-person="${p.id}"><div class="row-person"><div class="portrait">${initials(p.name)}</div><div><strong>${p.name}${p.watched?' ◉':''}</strong><small>${p.age.toFixed(0)} years · ${p.home}</small></div></div><div class="row-stat">WORK<b>${p.job}</b></div><div class="row-stat">KNOWN FOR<b>${p.traits[0]} · ${p.reputation>50?'Influence':'Community'}</b></div><span class="badge ${p.reputation>55?'gold':''}">${p.reputation>60?'Notable':'Neighbor'}</span></div>`).join('')||'<div class="empty-state">No people match this view yet.</div>'}</div>`}
function societyView(){let orgs=state.organizations;return`<div class="section-heading"><div><div class="section-kicker">SHARED PURPOSE · AUTONOMOUS INSTITUTIONS</div><h1>Society takes shape</h1><p>Communities organize around the things they need and believe in.</p></div><button class="primary-btn" data-action="found">＋ Found an organization</button></div>${tabs([['all','Institutions'],['relationships','Social web'],['settlement','Settlement']],state.subview)}${state.subview==='relationships'?socialView():state.subview==='settlement'?settlementView():`<div class="two-col">${orgs.map(o=>`<div class="panel-card"><div class="panel-head"><div><span class="section-kicker">${o.kind.toUpperCase()} · YEAR ${Math.max(1,state.year-Math.floor(o.age/3))}</span><h2 style="margin-top:5px">${o.name}</h2></div><span class="badge">${o.members.length} members</span></div><p class="inspector-p">${o.objective}</p><div class="quick-stat"><span>Community influence</span><strong>${Math.round(o.influence)} / 100</strong></div><div class="meter"><i style="width:${o.influence}%"></i></div><div class="quick-stat"><span>Shared resources</span><strong>${Math.round(o.resources)}%</strong></div><div class="quick-stat"><span>Leadership</span><strong>${state.people.find(p=>p.id===o.leader)?.name||'Community'}</strong></div><button class="small-action" data-action="join" data-org="${o.id}">${o.members.includes(state.focus)?'You are a member':'Join the organization'}</button></div>`).join('')}</div><div class="panel-card" style="margin-top:14px"><div class="panel-head"><h2>How influence travels</h2><span class="tiny-label">SOCIAL NETWORK</span></div><p class="inspector-p">Trust shapes who shares opportunities. Organizations recruit through friendship, leadership grows from reputation, and their decisions feed back into employment, policy, and household wellbeing. Nothing here is pre-written.</p></div>`}`}
function socialView(){return`<div class="panel-card"><div class="panel-head"><h2>Relationship web</h2><span class="tiny-label">${state.relationships.length} ACTIVE TIES</span></div>${state.relationships.slice().sort((a,b)=>b.influence-a.influence).map(r=>{let a=state.people.find(p=>p.id===r.a),b=state.people.find(p=>p.id===r.b);return`<div class="relationship-card"><div class="portrait">${initials(a?.name||'?')}</div><div><strong>${a?.name||'Unknown'} ↔ ${b?.name||'Unknown'}</strong><small>${r.type} · Trust ${r.trust}% · Affection ${r.affection}%</small></div><span>${r.influence}% influence</span></div>`}).join('')}</div>`}
function settlementView(){let s=state.settlement;return`<div class="two-col"><div class="panel-card"><div class="panel-head"><h2>${s.name} plan</h2><span class="badge">${s.population} residents</span></div><p class="inspector-p">The village grows in response to population, shared needs, local resources, and decisions made at community meetings.</p>${[['Homes',s.houses,'⌂'],['Fields',s.fields,'▦'],['Workshops',s.workshops,'⚒'],['Roads & paths',s.roads,'⌁'],['Water points',s.waterworks,'◉'],['Commons',s.commons,'◇']].map(([n,v,i])=>`<div class="quick-stat"><span>${i} &nbsp; ${n}</span><strong>${v}</strong></div>`).join('')}</div><div class="panel-card"><div class="panel-head"><h2>Community projects</h2><span class="tiny-label">COLLECTIVE DECISIONS</span></div><p class="inspector-p">Each project costs shared resources. Neighbors weigh urgent needs against long-term growth.</p><div class="event-row"><span class="event-marker">▦</span><div class="event-copy"><strong>Expand the shared fields</strong><p>Improves food resilience and provides seasonal work.</p></div><button class="small-action" data-action="field">Build · 8</button></div><div class="event-row"><span class="event-marker">⌂</span><div class="event-copy"><strong>Raise a new home</strong><p>Make room for new families and returning neighbors.</p></div><button class="small-action" data-action="house">Build · 6</button></div><div class="event-row"><span class="event-marker">◉</span><div class="event-copy"><strong>Repair the well</strong><p>Protect clean water through a dry season.</p></div><button class="small-action" data-action="well">Build · 7</button></div></div></div>`}

