function render(){if(!state.people||!state.events||!state.settlement)state=seedWorld();$('#dateLabel').textContent=currentDate();$('#worldName').textContent=state.settlement.name==='Aster Hollow'?'The Vale of Aster':state.settlement.name;$('#playIcon').textContent=state.paused?'▶':'Ⅱ';$('#playText').textContent=state.paused?'RESUME':'PAUSE';$('#footerPopulation').textContent=`${state.settlement.population} people · ${state.organizations.length} organizations · ${state.events.length} remembered events`;$('#footerNotice').textContent=state.events[0]?.title||'Every life leaves a trace.';$$('.rail-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$$('.speed-btn').forEach(b=>b.classList.toggle('selected',Number(b.dataset.speed)===state.speed));renderMain();renderInspector()}
function showModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function chooseRole(){showModal(`<span class="section-kicker">PERSPECTIVE IS A CHOICE</span><h2>Whose life will you live?</h2><p>The world continues either way. Pick a point of view; the simulation stays the same.</p><div class="modal-options">${[['Neighbor','A daily life among friends and family.'],['Maker','Build a craft, business, or shared institution.'],['Explorer','Follow roads, resources, and new settlements.'],['Council voice','Help shape public choices and trust.']].map(([a,b])=>`<button class="role-option" data-role="${a}"><strong>${a}</strong><small>${b}</small></button>`).join('')}</div><div class="modal-actions"><button class="secondary-btn" data-close>Maybe later</button></div>`)}
function policyModal(){showModal(`<span class="section-kicker">PUBLIC CHOICE · CONSEQUENCES FOLLOW</span><h2>What should the council do?</h2><p>Policy changes household life and long-term public trust. The community will feel the tradeoffs.</p><label class="tiny-label">COMMUNITY LEVY: <b id="taxRead">${state.policies.tax}%</b></label><input id="taxSlider" type="range" min="2" max="20" value="${state.policies.tax}" style="width:100%;margin:12px 0"><label style="display:flex;align-items:center;gap:8px;font-size:11px;color:#627064"><input id="reliefCheck" type="checkbox" ${state.policies.relief?'checked':''}> Keep grain relief active (supports households, draws down reserves)</label><div class="modal-actions"><button class="secondary-btn" data-close>Cancel</button><button class="primary-btn" data-action="applyPolicy">Apply policy</button></div>`)}
function handleAction(action,el){if(action==='watch'){let p=state.people.find(x=>x.id===el.dataset.person)||focusPerson();p.watched=!p.watched;showToast(p.watched?'Following '+p.name+' through their life.':'Stopped following this life.');save();render();return}
